import pandas as pd


def run(inputs: dict) -> dict:
    orders = inputs["orders"].copy()
    ref_customers = inputs["ref_customers"].copy()
    ref_skus = inputs["ref_skus"].copy()

    # Build lookup dicts, first occurrence wins for duplicate keys
    cust_status = {}
    for _, row in ref_customers.iterrows():
        cid = row["customer_id"]
        if cid not in cust_status:
            cust_status[cid] = row["status"]

    sku_info = {}
    for _, row in ref_skus.iterrows():
        s = row["sku"]
        if s not in sku_info:
            sku_info[s] = (row["discontinued"], row["allowed_countries"])

    reason_codes = []

    for _, row in orders.iterrows():
        cid = row["customer_id"]
        sku = row["sku"]
        ship_country = row["ship_country"]

        reason = None

        if cid not in cust_status:
            reason = "CUST_UNKNOWN"
        elif cust_status[cid] != "ACTIVE":
            reason = "CUST_INACTIVE"
        elif sku not in sku_info:
            reason = "SKU_UNKNOWN"
        else:
            discontinued, allowed_countries = sku_info[sku]
            if discontinued == 1:
                reason = "SKU_DISC"
            else:
                if allowed_countries is not None and pd.notna(allowed_countries):
                    allowed_str = str(allowed_countries).strip()
                else:
                    allowed_str = ""

                if allowed_str != "":
                    members = [m.strip() for m in allowed_str.split(",")]
                    sc = str(ship_country).strip() if pd.notna(ship_country) else ship_country
                    if sc not in members:
                        reason = "CTRY_BLOCKED"

        reason_codes.append(reason)

    orders["_reason_code"] = reason_codes

    clean_mask = orders["_reason_code"].isna()
    orders_clean = orders.loc[clean_mask, ["order_id", "customer_id", "sku", "qty", "ship_country"]].reset_index(drop=True)

    rejects = orders.loc[~clean_mask, ["order_id", "customer_id", "sku", "qty", "ship_country", "_reason_code"]].reset_index(drop=True)
    rejects = rejects.rename(columns={"_reason_code": "reason_code"})

    return {
        "orders_clean": orders_clean,
        "orders_rejects": rejects,
    }
